<?php
namespace App\Controllers;
use App\Core\Database;
final class CtaController{public function index():void{$db=Database::db();$cta=$db->query('SELECT * FROM homepage_cta WHERE id=1')->fetch()?:[];$events=$db->query('SELECT id,name,event_date FROM events ORDER BY event_date DESC')->fetchAll();admin_view('admin/cta',['cta'=>$cta,'events'=>$events,'pageTitle'=>'CTA de portada','adminSection'=>'cta']);}public function save():never{verify_csrf();$s=Database::db()->prepare("INSERT INTO homepage_cta(id,event_id,eyebrow,title,description,button_text,button_url,image_url,active) VALUES(1,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE event_id=VALUES(event_id),eyebrow=VALUES(eyebrow),title=VALUES(title),description=VALUES(description),button_text=VALUES(button_text),button_url=VALUES(button_url),image_url=VALUES(image_url),active=VALUES(active)");$s->execute([(int)($_POST['event_id']??0)?:null,trim($_POST['eyebrow']??''),trim($_POST['title']??''),trim($_POST['description']??''),trim($_POST['button_text']??''),trim($_POST['button_url']??''),trim($_POST['image_url']??''),isset($_POST['active'])?1:0]);$_SESSION['success']='CTA actualizado correctamente.';redirect('/admin/cta');}}

